<?php
namespace Modules\Glitter\Workflow\Jobs;
use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Support\Facades\DB;use Modules\Glitter\Workflow\Enums\{ActionExecutionStatus,WorkflowExecutionStatus};use Modules\Glitter\Workflow\Models\WorkflowActionExecution;
final class ProcessWorkflowDelayResumeJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable;public int $tries=3;public int $timeout=30;public function __construct(public readonly string $actionUuid){$this->afterCommit=true;}public function handle():void{$a=DB::transaction(function(){$a=WorkflowActionExecution::query()->where('uuid',$this->actionUuid)->lockForUpdate()->first();if(!$a||$a->status!==ActionExecutionStatus::Scheduled||!$a->scheduled_at||$a->scheduled_at->isFuture())return null;$a->status=ActionExecutionStatus::Succeeded;$a->finished_at=now();$a->save();return $a;});if(!$a)return;ProcessWorkflowExecutionJob::dispatch($a->execution->uuid);}}
